import json,re,pathlib
P=pathlib.Path(__file__).parent
jobs=[]
def add(src,pattern,topic,segment,fmt,level,why,task,angle,limit=35,risk='Проверить содержание',n=1):
 index=json.loads((P/(src+'-index.json')).read_text(encoding='utf-8-sig'))
 matches=[e for e in index['entries'] if re.search(pattern,e.get('title') or '')][:n]
 if not matches: print('NO MATCH',src,pattern);return
 for e in matches:
  jobs.append(dict(id=f'C{len(jobs)+1:03}',url=e.get('url') or 'https://www.youtube.com/playlist?list='+e['id'],source=src,title=e['title'],topic=topic,segment=segment,format=fmt,level=level,why=why,task=task,angle=angle,limit=limit,risk=risk))
